//! One catch-all shape for every open enum (roadmap L20a): `Other(String)`,
//! generated by `meta_whatsapp_core::open_enum!`.
//!
//! Two halves, the decisive test of the roadmap item:
//!
//! - **The round trip.** Every enum the macro generates, in every crate, is
//!   listed in [`checked`], and a value no Meta page lists deserializes
//!   into `Other` holding it verbatim, serializes back unchanged, and reads
//!   the same through `From<&str>`, `FromStr` and `Display`; a number is
//!   kept as its JSON text, unless the enum is `#![string_only]`. The list
//!   is compared with what the source declares, so an enum added to the
//!   macro and not here fails.
//! - **The scan.** No enum of the source has a catch-all of another shape:
//!   no `#[serde(other)]`, no unit `Unknown`, no hand-written `Other(String)`
//!   or `Unknown(String)`, outside the few listed in [`NOT_OPEN`] with the
//!   reason each is not an open enum. A unit `Unknown` inside the macro must
//!   be Meta's documented `UNKNOWN`.
//!
//! What is left as it is, on purpose: the enums whose catch-all keeps a
//! structured raw value (`Unknown { raw }` on webhook messages and fields,
//! `WebhookEvent::Unparsed`, Flow JSON's components and actions, the
//! templates' `Other(Value)` components): they are not string enums.
#![allow(clippy::unwrap_used, clippy::expect_used)] // test crate: a panic is the report

use std::any::type_name;
use std::collections::{BTreeMap, BTreeSet};
use std::fmt::{Debug, Display};
use std::fs;
use std::path::{Path, PathBuf};
use std::str::FromStr;

use meta_whatsapp_rs::{client, webhooks};
use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::json;

/// Values no Meta page lists for any of the enums: spelled in upper case,
/// lower case and mixed, with spaces and around whitespace, so that the
/// case-insensitive and normalizing enums are tested too. (Not the empty
/// string: `ProductReviewStatus` documents it.)
const UNLISTED: &[&str] = &[
    "A_VALUE_NO_PAGE_LISTS",
    "a value no page lists",
    " Mixed_Case value ",
];

/// One enum's round trip; its type name and whether it kept a number, for
/// the comparison with the source.
fn round_trip<T>() -> (&'static str, bool)
where
    T: Serialize + DeserializeOwned + Debug + Display + PartialEq + FromStr,
    T: for<'a> From<&'a str> + From<String>,
    <T as FromStr>::Err: Debug,
{
    let name = type_name::<T>();
    for &raw in UNLISTED {
        let read: T = serde_json::from_value(json!(raw))
            .unwrap_or_else(|e| panic!("{name}: {raw:?} fails to parse: {e}"));
        assert_eq!(
            format!("{read:?}"),
            format!("Other({raw:?})"),
            "{name}: {raw:?} is not kept verbatim in `Other`"
        );
        assert_eq!(
            serde_json::to_value(&read).unwrap(),
            json!(raw),
            "{name}: {raw:?} does not serialize back unchanged"
        );
        assert_eq!(read.to_string(), raw, "{name}: Display of {raw:?}");
        assert_eq!(T::from(raw), read, "{name}: From<&str> of {raw:?}");
        assert_eq!(T::from(raw.to_owned()), read, "{name}: From<String>");
        assert_eq!(
            raw.parse::<T>().unwrap(),
            read,
            "{name}: FromStr of {raw:?}"
        );
    }
    // A non-string value is kept as its JSON text, or refused (only by a
    // `#![string_only]` enum, which the test compares with the source).
    let kept = match serde_json::from_value::<T>(json!(42)) {
        Ok(number) => {
            assert_eq!(format!("{number:?}"), r#"Other("42")"#, "{name}: a number");
            true
        }
        Err(_) => false,
    };
    (name, kept)
}

macro_rules! round_trips {
    ($($(#[$attr:meta])* $ty:ty),+ $(,)?) => {{
        let mut names = BTreeMap::new();
        $(
            $(#[$attr])*
            {
                let (name, kept) = round_trip::<$ty>();
                names.insert(name, kept);
            }
        )+
        names
    }};
}

