/// Enums with a variant the scan would read as a catch-all, and why each
/// is not an open enum. Each must still be there and still trip the scan,
/// so the list cannot outlive what it excuses.
const NOT_OPEN: &[(&str, &str)] = &[
    (
        "meta_whatsapp_core::error::graph::ErrorKind",
        "this crate's classification of a failure, never read from or written to Meta; `Unknown` is a kind",
    ),
    (
        "meta_whatsapp_bot::jobs::memory::Mark",
        "a send whose outcome is unknown, a state of the bot's jobs, not a value of Meta's",
    ),
    (
        "meta_whatsapp_bot::jobs::port::RecipientMark",
        "a send whose outcome is unknown, a state of the bot's jobs, not a value of Meta's",
    ),
    (
        "meta_whatsapp_bot::jobs::runner::Outcome",
        "a send whose outcome is unknown, a state of the bot's jobs, not a value of Meta's",
    ),
    (
        "meta_whatsapp_bot::jobs::store::MarkerState",
        "the stored state `unknown` (outcome unknown) of the bot's jobs, written by this crate: a closed set",
    ),
    (
        "meta_whatsapp_client::credit_lines::WabaCurrency",
        "a request value Meta never sends: `Other` is chosen on purpose, and parsing refuses an unlisted code (`FromStr` fails), which the macro's infallible parse would undo",
    ),
    (
        "meta_whatsapp_client::messages::payments::GatewayProvider",
        "a request union whose listed variants carry each gateway's fields; `Other` only names a gateway",
    ),
];

#[test]
fn every_open_enum_keeps_an_unlisted_value_verbatim() {
    let checked = checked();
    let scan = scan();
    let declared = &scan.macro_enums;
    assert!(declared.len() > 150, "the scan found only {declared:?}");
    let missing: Vec<&String> = declared
        .iter()
        .filter(|name| !checked.contains_key(name.as_str()))
        .filter(|name| cfg!(feature = "flows-endpoint") || !name.contains("::flows::endpoint::"))
        .collect();
    let stale: Vec<&&str> = checked
        .keys()
        .filter(|name| !declared.contains(**name))
        .collect();
    assert!(
        missing.is_empty(),
        "`open_enum!` enums not in `checked()`: {missing:#?}"
    );
    assert!(
        stale.is_empty(),
        "`checked()` lists types no `open_enum!` declares (by their defining path): {stale:#?}"
    );
    for (name, kept) in &checked {
        assert_eq!(
            !kept,
            scan.string_only.contains(*name),
            "{name}: refuses a number exactly when it is `#![string_only]`"
        );
    }
    // Which enums are `#![string_only]` is decided (roadmap L20a): Flow
    // JSON's, a document this crate writes and reads back whole, so that
    // a wrongly typed value leaves its component raw; no other.
    let flow_json: BTreeSet<&String> = declared
        .iter()
        .filter(|name| name.starts_with("meta_whatsapp_client::flows::flow_json::"))
        .collect();
    assert!(flow_json.len() >= 10, "Flow JSON's enums: {flow_json:?}");
    assert_eq!(
        scan.string_only.iter().collect::<BTreeSet<_>>(),
        flow_json,
        "`#![string_only]` is for Flow JSON's enums, and every one of them"
    );
}

#[test]
fn no_enum_has_a_catch_all_of_another_shape() {
    let scan = scan();
    assert!(
        scan.violations.is_empty(),
        "catch-alls that are not `open_enum!`'s `Other(String)`:\n{}",
        scan.violations.join("\n")
    );
    for (name, why) in NOT_OPEN {
        assert!(
            scan.excused.contains(*name),
            "{name} is excused ({why}) but no longer trips the scan: remove it from NOT_OPEN"
        );
    }
}

#[test]
fn the_scan_catches_each_shape() {
    let file = |text: &str| {
        let mut scan = Scan::default();
        scan.file("meta_whatsapp_client::sample", text);
        scan
    };
    let unit = file(
        "#[derive(Deserialize)]\npub enum Status {\n    Active,\n    #[serde(other)]\n    Unknown,\n}\n",
    );
    assert_eq!(unit.violations.len(), 2, "{:?}", unit.violations);
    let hand = file("pub enum Status {\n    Active,\n    Other(String),\n}\n");
    assert_eq!(hand.violations.len(), 1, "{:?}", hand.violations);
    let untagged = file(
        "pub enum Status {\n    Active,\n    #[serde(untagged)]\n    Raw(std::string::String),\n}\n",
    );
    assert_eq!(untagged.violations.len(), 1, "{:?}", untagged.violations);
    for payload in [
        "Box<str>",
        "std::borrow::Cow<'static, str>",
        "Arc<str>",
        "Rc<String>",
        "::std::string::String",
    ] {
        let boxed = file(&format!(
            "pub enum Status {{\n    Active,\n    Other({payload}),\n}}\n"
        ));
        assert_eq!(
            boxed.violations.len(),
            1,
            "{payload}: {:?}",
            boxed.violations
        );
    }
    let named = file("pub enum Status {\n    Active,\n    Other { value: String },\n}\n");
    assert_eq!(named.violations.len(), 1, "{:?}", named.violations);
    let raw = file(
        "pub enum Message {\n    Text(String),\n    Unknown {\n        kind: Option<String>,\n        raw: Value,\n    },\n    Other(Value),\n}\n",
    );
    assert!(
        raw.violations.is_empty(),
        "structured: {:?}",
        raw.violations
    );
    let wrong =
        file("open_enum! {\n    pub enum Status {\n        Unknown => \"UNSET\",\n    }\n}\n");
    assert_eq!(wrong.violations.len(), 1, "{:?}", wrong.violations);
    let clean = file(
        "// enum Old { Unknown, } in a comment\nopen_enum! {\n    #![case_insensitive]\n    /// Docs.\n    pub enum Status {\n        /// `UNKNOWN`.\n        Unknown => \"UNKNOWN\",\n        Active => \"ACTIVE\" | \"active\",\n    }\n}\nconst S: &str = \"enum X { Unknown, }\";\n#[cfg(test)]\nmod tests {\n    open_enum! {\n        enum Sample {\n            A => \"a\",\n        }\n    }\n}\n",
    );
    assert!(clean.violations.is_empty(), "{:?}", clean.violations);
    assert_eq!(
        clean.macro_enums,
        BTreeSet::from(["meta_whatsapp_client::sample::Status".to_owned()])
    );
}

// ── The scan ─────────────────────────────────────────────────────────────

#[derive(Default)]
struct Scan {
    /// `open_enum!` enums outside test modules, by defining path.
    macro_enums: BTreeSet<String>,
    /// Those of them that are `#![string_only]`.
    string_only: BTreeSet<String>,
    /// Catch-alls of another shape, as `path: what`.
    violations: Vec<String>,
    /// The [`NOT_OPEN`] enums the scan met.
    excused: BTreeSet<String>,
}

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap()
}

fn rust_files(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            rust_files(&path, out);
        } else if path.extension().is_some_and(|e| e == "rs") {
            out.push(path);
        }
    }
}

/// Every library, service and tool source file (`crates/*/src`, and
/// `tools/*/src` for the Rust tools that are workspace members, such as
/// `tools/docs-mcp`).
fn scan() -> Scan {
    let mut scan = Scan::default();
    let mut dirs: Vec<PathBuf> = ["crates", "tools"]
        .into_iter()
        .flat_map(|parent| fs::read_dir(repo().join(parent)).unwrap())
        .map(|e| e.unwrap().path())
        .filter(|krate| krate.join("Cargo.toml").is_file())
        .map(|krate| krate.join("src"))
        .filter(|src| src.is_dir())
        .collect();
    dirs.sort();
    assert!(dirs.len() >= 10, "found only {dirs:?}");
    assert!(
        dirs.iter().any(|d| d.ends_with("tools/docs-mcp/src")),
        "the scan misses tools/docs-mcp: {dirs:?}"
    );
    for src in dirs {
        let krate = src
            .parent()
            .unwrap()
            .file_name()
            .unwrap()
            .to_str()
            .unwrap()
            .replace('-', "_");
        let mut files = Vec::new();
        rust_files(&src, &mut files);
        files.sort();
        for file in files {
            let rel = file.strip_prefix(&src).unwrap();
            let mut module = vec![krate.clone()];
            for part in rel.components() {
                let part = part.as_os_str().to_str().unwrap();
                match part.strip_suffix(".rs") {
                    Some("mod" | "lib" | "main") => {}
                    Some(stem) => module.push(stem.to_owned()),
                    None => module.push(part.to_owned()),
                }
            }
            let text = fs::read_to_string(&file).unwrap();
            scan.file(&module.join("::"), &text);
        }
    }
    scan
}

/// Where a file's `open_enum! {…}` and `macro_rules! … {…}` bodies, test
/// modules and inline modules are (byte spans of their braces).
#[derive(Default)]
struct Spans {
    macros: Vec<(usize, usize)>,
    rules: Vec<(usize, usize)>,
    tests: Vec<(usize, usize)>,
    modules: Vec<(usize, usize, String)>,
}

impl Spans {
    fn of(skeleton: &str) -> Self {
        let bytes = skeleton.as_bytes();
        let mut spans = Self::default();
        for (at, word) in words(skeleton) {
            match word {
                "open_enum" if bytes.get(at + word.len()) == Some(&b'!') => {
                    if let Some(open) = next_brace(skeleton, at) {
                        spans.macros.push((open, matching(bytes, open)));
                    }
                }
                "macro_rules" => {
                    if let Some(open) = next_brace(skeleton, at) {
                        spans.rules.push((open, matching(bytes, open)));
                    }
                }
                "mod" => {
                    let rest = skeleton[at + 3..].trim_start();
                    let name = ident(rest);
                    let after = rest[name.len()..].trim_start();
                    if name.is_empty() || !after.starts_with('{') {
                        continue;
                    }
                    let open = skeleton.len() - after.len();
                    let span = (open, matching(bytes, open));
                    if skeleton[..at].trim_end().ends_with("#[cfg(test)]") || name == "tests" {
                        spans.tests.push(span);
                    }
                    spans.modules.push((span.0, span.1, name));
                }
                _ => {}
            }
        }
        spans
    }

    /// The span of `spans` that holds `at`.
    fn around(spans: &[(usize, usize)], at: usize) -> Option<(usize, usize)> {
        spans.iter().copied().find(|&(a, b)| a < at && at < b)
    }

    /// `module` plus the inline modules around `at`, then `name`.
    fn path(&self, module: &str, at: usize, name: &str) -> String {
        let mut path = module.to_owned();
        for (a, b, m) in &self.modules {
            if *a < at && at < *b {
                path.push_str("::");
                path.push_str(m);
            }
        }
        format!("{path}::{name}")
    }
}

/// The identifier `text` starts with.
fn ident(text: &str) -> String {
    text.chars()
        .take_while(|c| c.is_alphanumeric() || *c == '_')
        .collect()
}

/// A type that holds a string and nothing else: `String`, `Box<str>`,
/// `Cow<'_, str>`, `Arc<str>`, `Rc<str>`, by any path.
fn is_string_type(ty: &str) -> bool {
    let ty: String = ty.chars().filter(|c| !c.is_whitespace()).collect();
    let last = |t: &str| t.rsplit("::").next().unwrap_or(t).to_owned();
    if last(&ty) == "String" {
        return true;
    }
    let Some((outer, inner)) = ty.strip_suffix('>').and_then(|t| t.split_once('<')) else {
        return false;
    };
    let inner = inner.rsplit(',').next().unwrap_or(inner);
    matches!(last(outer).as_str(), "Box" | "Cow" | "Arc" | "Rc")
        && (inner == "str" || last(inner) == "String")
}

/// What makes a hand-written enum's variants a catch-all of another shape.
fn hand_written_catch_alls(variants: &[(String, String)]) -> Vec<&'static str> {
    let mut tripped = Vec::new();
    for (attrs, body) in variants {
        let body = body.trim();
        let (variant, payload) = match body.split_once('(') {
            Some((v, p)) => (v.trim(), Some(p.trim_end_matches(')').trim())),
            None => match body.split_once('{') {
                // A struct variant of one field is a tuple variant by
                // another name (`Other { value: String }`).
                Some((v, fields)) => {
                    let fields = fields.trim_end_matches('}').trim().trim_end_matches(',');
                    let one = (!fields.contains(','))
                        .then(|| fields.split_once(':').map(|(_, ty)| ty.trim()))
                        .flatten();
                    (v.trim(), one)
                }
                None => (body.split('=').next().unwrap().trim(), None),
            },
        };
        let stringy = payload.is_some_and(is_string_type);
        if variant == "Unknown" && payload.is_none() && !body.contains('{') {
            tripped.push("a unit `Unknown`");
        }
        if stringy && matches!(variant, "Other" | "Unknown") {
            tripped.push("a hand-written string catch-all");
        } else if stringy && attrs.contains("untagged") {
            tripped.push("an untagged string catch-all");
        }
    }
    tripped
}

impl Scan {
    /// Scan one file, whose module path is `module`.
    fn file(&mut self, module: &str, text: &str) {
        let code = mask(text, false);
        let skeleton = mask(text, true);
        let bytes = skeleton.as_bytes();
        let spans = Spans::of(&skeleton);
        if let Some(at) = find_serde_other(&skeleton) {
            let line = skeleton[..at].lines().count();
            self.violations
                .push(format!("{module} (line {line}): `#[serde(other)]`"));
        }
        let test_file = module
            .split("::")
            .any(|m| m == "tests" || m.starts_with("tests_"));
        for (at, word) in words(&skeleton) {
            if word != "enum" || Spans::around(&spans.rules, at).is_some() {
                continue;
            }
            let name = ident(skeleton[at + 4..].trim_start());
            let Some(open) = next_brace(&skeleton, at).filter(|_| !name.is_empty()) else {
                continue;
            };
            let close = matching(bytes, open);
            let path = spans.path(module, at, &name);
            let variants = split_variants(&code[open + 1..close], &skeleton[open + 1..close]);
            if let Some((invocation, _)) = Spans::around(&spans.macros, at) {
                if Spans::around(&spans.tests, at).is_none() && !test_file {
                    if skeleton[invocation..at].contains("#![string_only]") {
                        self.string_only.insert(path.clone());
                    }
                    self.macro_enums.insert(path.clone());
                }
                self.macro_variants(&path, &variants);
                continue;
            }
            let tripped = hand_written_catch_alls(&variants);
            if tripped.is_empty() {
                continue;
            }
            if NOT_OPEN.iter().any(|(n, _)| *n == path) {
                self.excused.insert(path);
            } else {
                for what in tripped {
                    self.violations.push(format!("{path}: {what}"));
                }
            }
        }
    }

    /// A unit `Unknown` inside the macro must be Meta's documented
    /// `UNKNOWN`.
    fn macro_variants(&mut self, path: &str, variants: &[(String, String)]) {
        for (_, body) in variants {
            let Some((variant, wire)) = body.split_once("=>") else {
                continue;
            };
            let first = wire.split('|').next().unwrap().trim().trim_matches('"');
            if variant.trim() == "Unknown" && !first.eq_ignore_ascii_case("unknown") {
                self.violations.push(format!(
                    "{path}: `Unknown => {first:?}`, a unit `Unknown` that is not Meta's `UNKNOWN`"
                ));
            }
        }
    }
}

/// `text` with comments blanked (and, with `strings`, the contents of
/// string and char literals too), byte for byte, so offsets agree.
fn mask(text: &str, strings: bool) -> String {
    let b = text.as_bytes();
    let mut out = b.to_vec();
    let blank = |out: &mut Vec<u8>, from: usize, to: usize| {
        for c in &mut out[from..to] {
            if *c != b'\n' {
                *c = b' ';
            }
        }
    };
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'/' if b.get(i + 1) == Some(&b'/') => {
                let end = b[i..]
                    .iter()
                    .position(|&c| c == b'\n')
                    .map_or(b.len(), |p| i + p);
                blank(&mut out, i, end);
                i = end;
            }
            b'/' if b.get(i + 1) == Some(&b'*') => {
                let mut depth = 0;
                let start = i;
                while i < b.len() {
                    if b[i..].starts_with(b"/*") {
                        depth += 1;
                        i += 2;
                    } else if b[i..].starts_with(b"*/") {
                        depth -= 1;
                        i += 2;
                        if depth == 0 {
                            break;
                        }
                    } else {
                        i += 1;
                    }
                }
                blank(&mut out, start, i);
            }
            b'r' if (b.get(i + 1) == Some(&b'"') || b.get(i + 1) == Some(&b'#'))
                && (i == 0 || !is_ident(b[i - 1])) =>
            {
                let hashes = b[i + 1..].iter().take_while(|&&c| c == b'#').count();
                if b.get(i + 1 + hashes) != Some(&b'"') {
                    i += 1;
                    continue;
                }
                let open = i + 1 + hashes;
                let mut close = String::from("\"");
                close.push_str(&"#".repeat(hashes));
                let end = text[open + 1..]
                    .find(&close)
                    .map_or(b.len(), |p| open + 1 + p);
                if strings {
                    blank(&mut out, open + 1, end);
                }
                i = end + close.len();
            }
            b'"' => {
                let start = i + 1;
                i += 1;
                while i < b.len() && b[i] != b'"' {
                    i += if b[i] == b'\\' { 2 } else { 1 };
                }
                if strings {
                    blank(&mut out, start, i.min(b.len()));
                }
                i += 1;
            }
            b'\'' => {
                // A char literal (`'x'`, `'\n'`, `'"'`), or a lifetime.
                let len = if b.get(i + 1) == Some(&b'\\') {
                    b[i + 2..].iter().position(|&c| c == b'\'').map(|p| p + 3)
                } else {
                    let ch = text[i + 1..].chars().next().map_or(1, char::len_utf8);
                    (b.get(i + 1 + ch) == Some(&b'\'')).then_some(ch + 1)
                };
                match len {
                    Some(len) => {
                        if strings {
                            blank(&mut out, i + 1, i + len);
                        }
                        i += len + 1;
                    }
                    None => i += 1,
                }
            }
            _ => i += 1,
        }
    }
    String::from_utf8(out).unwrap()
}

fn is_ident(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}

/// Each identifier-like word of `text`, with its offset.
fn words(text: &str) -> impl Iterator<Item = (usize, &str)> {
    let b = text.as_bytes();
    let mut i = 0;
    std::iter::from_fn(move || {
        while i < b.len() {
            if is_ident(b[i]) && (i == 0 || !is_ident(b[i - 1])) {
                let start = i;
                while i < b.len() && is_ident(b[i]) {
                    i += 1;
                }
                return Some((start, &text[start..i]));
            }
            i += 1;
        }
        None
    })
}

/// The first `{` after `at`, unless a `;` comes first (`mod x;`).
fn next_brace(text: &str, at: usize) -> Option<usize> {
    let rest = &text[at..];
    let open = rest.find('{')?;
    match rest.find(';') {
        Some(semi) if semi < open => None,
        _ => Some(at + open),
    }
}

/// The `}` matching the `{` at `open`.
fn matching(b: &[u8], open: usize) -> usize {
    let mut depth = 0;
    for (i, &c) in b.iter().enumerate().skip(open) {
        match c {
            b'{' => depth += 1,
            b'}' => {
                depth -= 1;
                if depth == 0 {
                    return i;
                }
            }
            _ => {}
        }
    }
    b.len()
}

/// An enum body's variants: `(attributes, the rest)`, split at the
/// top-level commas of the skeleton (`code` keeps the literals).
fn split_variants(code: &str, skeleton: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    let b = skeleton.as_bytes();
    let mut push = |from: usize, to: usize| {
        let part = &code[from..to];
        let mut attrs = String::new();
        let mut rest = part.trim_start();
        while rest.starts_with("#[") {
            let mut d = 0;
            let end = rest
                .char_indices()
                .find(|&(_, c)| {
                    match c {
                        '[' => d += 1,
                        ']' => d -= 1,
                        _ => {}
                    }
                    d == 0 && c == ']'
                })
                .map_or(rest.len(), |(i, _)| i + 1);
            attrs.push_str(&rest[..end]);
            rest = rest[end..].trim_start();
        }
        if !rest.trim().is_empty() {
            out.push((attrs, rest.trim().to_owned()));
        }
    };
    for (i, &c) in b.iter().enumerate() {
        match c {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth -= 1,
            b',' if depth == 0 => {
                push(start, i);
                start = i + 1;
            }
            _ => {}
        }
    }
    push(start, b.len());
    out
}

/// The offset of a `#[serde(…other…)]` attribute.
fn find_serde_other(skeleton: &str) -> Option<usize> {
    let mut from = 0;
    while let Some(p) = skeleton[from..].find("serde(") {
        let at = from + p;
        let args_start = at + "serde(".len();
        let end = skeleton[args_start..]
            .find(')')
            .map_or(skeleton.len(), |e| args_start + e);
        let args = &skeleton[args_start..end];
        if args.split(',').any(|a| a.trim() == "other") {
            return Some(at);
        }
        from = args_start;
    }
    None
}
